import { useEffect, useState } from "react";
import OtpInput from "./OtpInput.jsx";
import { inputClass, labelClass, primaryButton } from "../ui/styles.js";
import {
  getCurrentUser,
  requestOtp,
  verifyOtp,
} from "../../services/authService.js";
import {
  normalizeIdentifier,
  toPersianDigits,
  validateIdentifier,
} from "../../utils/identifier.js";

// Keep OTP_LENGTH in sync with the code length generated by the backend.
const OTP_LENGTH = 5;
const RESEND_SECONDS = 60;

function formatTimer(totalSeconds) {
  const minutes = String(Math.floor(totalSeconds / 60)).padStart(2, "0");
  const seconds = String(totalSeconds % 60).padStart(2, "0");
  return toPersianDigits(`${minutes}:${seconds}`);
}

export default function LoginForm({ onSuccess }) {
  const [step, setStep] = useState("identifier"); // "identifier" | "code"
  const [rawIdentifier, setRawIdentifier] = useState("");
  const [identifier, setIdentifier] = useState("");
  const [code, setCode] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [secondsLeft, setSecondsLeft] = useState(0);

  useEffect(() => {
    if (step !== "code" || secondsLeft <= 0) return undefined;
    const timer = setTimeout(() => setSecondsLeft((s) => s - 1), 1000);
    return () => clearTimeout(timer);
  }, [step, secondsLeft]);

  const sendCode = async (value) => {
    setLoading(true);
    setError("");
    try {
      await requestOtp(value);
      setIdentifier(value);
      setCode("");
      setSecondsLeft(RESEND_SECONDS);
      setStep("code");
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleIdentifierSubmit = (event) => {
    event.preventDefault();
    if (loading) return;
    const normalized = normalizeIdentifier(rawIdentifier);
    const validationError = validateIdentifier(normalized);
    if (validationError) {
      setError(validationError);
      return;
    }
    sendCode(normalized);
  };

  const handleVerifySubmit = async (event) => {
    event.preventDefault();
    if (loading) return;
    if (code.length !== OTP_LENGTH) {
      setError(`کد تایید ${toPersianDigits(OTP_LENGTH)} رقمی را کامل وارد کنید.`);
      return;
    }

    setLoading(true);
    setError("");
    try {
      await verifyOtp(identifier, code);
      let user;
      try {
        user = await getCurrentUser();
      } catch {
        throw new Error(
          "ورود انجام شد، اما نشست شما ذخیره نشد. تنظیمات کوکی مرورگر را بررسی کنید.",
        );
      }
      onSuccess?.(user);
    } catch (err) {
      setError(err.message);
      setCode("");
    } finally {
      setLoading(false);
    }
  };

  const handleBack = () => {
    setStep("identifier");
    setCode("");
    setError("");
    setSecondsLeft(0);
  };

  const errorBox = error ? (
    <p
      role="alert"
      className="rounded-xl bg-red-50 px-4 py-3 text-sm leading-6 text-red-700"
    >
      {error}
    </p>
  ) : null;

  if (step === "identifier") {
    return (
      <form onSubmit={handleIdentifierSubmit} noValidate className="space-y-5">
        <div>
          <h2 className="text-lg font-semibold">ورود یا ثبت‌نام</h2>
          <p className="mt-1.5 text-sm leading-7 text-text/60">
            شماره موبایل یا ایمیل خود را وارد کنید تا کد تایید برایتان ارسال شود.
          </p>
        </div>

        <div>
          <label htmlFor="identifier" className={labelClass}>
            شماره موبایل یا ایمیل
          </label>
          <input
            id="identifier"
            type="text"
            dir="ltr"
            autoComplete="username"
            autoFocus
            value={rawIdentifier}
            onChange={(event) => {
              setRawIdentifier(event.target.value);
              if (error) setError("");
            }}
            placeholder="09123456789"
            disabled={loading}
            className={`${inputClass} text-left`}
          />
        </div>

        {errorBox}

        <button type="submit" disabled={loading} className={`${primaryButton} w-full`}>
          {loading ? "در حال ارسال..." : "ارسال کد تایید"}
        </button>
      </form>
    );
  }

  return (
    <form onSubmit={handleVerifySubmit} noValidate className="space-y-5">
      <div>
        <h2 className="text-lg font-semibold">کد تایید را وارد کنید</h2>
        <p className="mt-1.5 text-sm leading-7 text-text/60">
          کد {toPersianDigits(OTP_LENGTH)} رقمی برای{" "}
          <span dir="ltr" className="inline-block font-medium text-text">
            {identifier}
          </span>{" "}
          ارسال شد. این کد تا ۳ دقیقه معتبر است.
        </p>
      </div>

      <OtpInput
        length={OTP_LENGTH}
        value={code}
        onChange={(next) => {
          setCode(next);
          if (error) setError("");
        }}
        disabled={loading}
        hasError={Boolean(error)}
      />

      {errorBox}

      <button
        type="submit"
        disabled={loading || code.length !== OTP_LENGTH}
        className={`${primaryButton} w-full`}
      >
        {loading ? "در حال بررسی..." : "تایید و ورود"}
      </button>

      <div className="flex items-center justify-between text-sm">
        <button
          type="button"
          onClick={handleBack}
          disabled={loading}
          className="font-medium text-primary hover:underline disabled:opacity-60"
        >
          ویرایش شماره یا ایمیل
        </button>
        <button
          type="button"
          onClick={() => sendCode(identifier)}
          disabled={loading || secondsLeft > 0}
          className="font-medium text-primary hover:underline disabled:cursor-not-allowed disabled:text-text/40 disabled:no-underline"
        >
          {secondsLeft > 0
            ? `ارسال مجدد تا ${formatTimer(secondsLeft)}`
            : "ارسال مجدد کد"}
        </button>
      </div>
    </form>
  );
}
